        {
          "quote_id": "concern_001.s3.q1"
        },
        {
          "quote_id": "concern_001.s3.q2"
        },
        {
          "quote_id": "concern_001.s1.q2"
        }
      ]
    },
    {
      "component_id": "concern_002",
      "text": "Suppliers of durable consumer products are jointly liable for imperfections that make the product unfit or diminish its value, and the consumer may demand remedies if the defect is not corrected within thirty (30) days. The consumer may choose (a) replacement with a perfect product of the same kind, (b) immediate reimbursement of the purchase price with monetary updating, or (c) a proportionate price reduction. Immediate use of these alternatives is allowed when repairing the defect would jeopardize product quality.",
      "evidence": [
        {
          "quote_id": "concern_002.s1.q1"
        },
        {
          "quote_id": "concern_002.s1.q2"
        },
        {
